import React from 'react';
import { cardStyleKeys } from '../lib/core';
import type {
	CardBaseProps,
	CardHeaderBaseProps,
	CardTitleBaseProps,
	CardDescriptionBaseProps,
	CardActionBaseProps,
	CardContentBaseProps,
	CardFooterBaseProps,
} from '../lib/core';
import styles from './card.module.scss';

export interface CardProps extends React.HTMLAttributes<HTMLDivElement>, CardBaseProps {}

const Card = React.forwardRef<HTMLDivElement, CardProps>(({ className = '', as: Component = 'div', children, ...props }, ref) => {
	return (
		<Component ref={ref} className={`${styles[cardStyleKeys.card]} ${className}`} {...props}>
			{children}
		</Component>
	);
});
Card.displayName = 'Card';

interface CardHeaderProps extends React.HTMLAttributes<HTMLDivElement>, CardHeaderBaseProps {}

const CardHeader = React.forwardRef<HTMLDivElement, CardHeaderProps>(({ className = '', children, ...props }, ref) => {
	return (
		<div ref={ref} className={`${styles[cardStyleKeys.header]} ${className}`} {...props}>
			{children}
		</div>
	);
});
CardHeader.displayName = 'CardHeader';

interface CardTitleProps extends React.HTMLAttributes<HTMLHeadingElement>, CardTitleBaseProps {}

const CardTitle = React.forwardRef<HTMLHeadingElement, CardTitleProps>(({ className = '', children, ...props }, ref) => {
	return (
		<h3 ref={ref} className={`${styles[cardStyleKeys.title]} ${className}`} {...props}>
			{children}
		</h3>
	);
});
CardTitle.displayName = 'CardTitle';

interface CardDescriptionProps extends React.HTMLAttributes<HTMLParagraphElement>, CardDescriptionBaseProps {}

const CardDescription = React.forwardRef<HTMLParagraphElement, CardDescriptionProps>(({ className = '', children, ...props }, ref) => {
	return (
		<p ref={ref} className={`${styles[cardStyleKeys.description]} ${className}`} {...props}>
			{children}
		</p>
	);
});
CardDescription.displayName = 'CardDescription';

interface CardActionProps extends React.HTMLAttributes<HTMLDivElement>, CardActionBaseProps {}

const CardAction = React.forwardRef<HTMLDivElement, CardActionProps>(({ className = '', children, ...props }, ref) => {
	return (
		<div ref={ref} className={`${styles[cardStyleKeys.action]} ${className}`} {...props}>
			{children}
		</div>
	);
});
CardAction.displayName = 'CardAction';

interface CardContentProps extends React.HTMLAttributes<HTMLDivElement>, CardContentBaseProps {}

const CardContent = React.forwardRef<HTMLDivElement, CardContentProps>(({ className = '', children, ...props }, ref) => {
	return (
		<div ref={ref} className={`${styles[cardStyleKeys.content]} ${className}`} {...props}>
			{children}
		</div>
	);
});
CardContent.displayName = 'CardContent';

interface CardFooterProps extends React.HTMLAttributes<HTMLDivElement>, CardFooterBaseProps {}

const CardFooter = React.forwardRef<HTMLDivElement, CardFooterProps>(({ className = '', children, ...props }, ref) => {
	return (
		<div ref={ref} className={`${styles[cardStyleKeys.footer]} ${className}`} {...props}>
			{children}
		</div>
	);
});
CardFooter.displayName = 'CardFooter';

export { Card, CardHeader, CardTitle, CardDescription, CardAction, CardContent, CardFooter };
export type { CardHeaderProps, CardTitleProps, CardDescriptionProps, CardActionProps, CardContentProps, CardFooterProps };
export default Card;

@use '../../../styles/variables/colors' as *;

.card {
	display: flex;
	flex-direction: column;
	gap: var(--tile-card-gap, $spacing-4);
	border-radius: var(--tile-card-radius, $radius-lg);
	border: 1px solid var(--tile-card-border, $border);
	background-color: var(--tile-card-background, $background);
	color: $foreground;
	box-shadow: var(--tile-card-shadow, $shadow);
	overflow: hidden;
	transition: box-shadow $transition-normal;

	&:hover {
		box-shadow: var(--tile-card-hover-shadow, $shadow-md);
	}
}

.cardHeader {
	display: grid;
	grid-template-columns: 1fr;
	grid-auto-rows: min-content;
	align-items: start;
	gap: $spacing-1;
	padding: var(--tile-card-header-padding, $spacing-6 $spacing-6 0);

	// 存在操作区时启用右侧列
	&:has(.cardAction) {
		grid-template-columns: 1fr auto;
	}
}

.cardTitle {
	font-size: var(--tile-card-title-size, $text-xl);
	font-weight: var(--tile-card-title-weight, $font-semibold);
	line-height: var(--tile-card-title-leading, $leading-tight);
	color: $foreground;
	margin: 0;
}

.cardDescription {
	font-size: $text-sm;
	color: var(--tile-card-description-color, $muted-foreground);
	line-height: $leading-normal;
	margin: 0;
}

.cardAction {
	grid-column-start: 2;
	grid-row-start: 1;
	grid-row-end: span 2;
	align-self: start;
	justify-self: end;
}

.cardContent {
	padding: var(--tile-card-content-padding, 0 $spacing-6);
}

.cardFooter {
	display: flex;
	align-items: center;
	gap: $spacing-4;
	padding: var(--tile-card-footer-padding, 0 $spacing-6 $spacing-6);
}
